function authErrorMessage(error) {
  const text = `${error?.code || ''} ${error?.name || ''} ${error?.message || error || ''}`.toLowerCase();
  if (text.includes('timeout')) return 'O Supabase demorou para responder. Verifique sua conexão e tente novamente.';
  if (/email not confirmed|email_not_confirmed/.test(text)) return 'Confirme o e-mail da conta no Supabase antes de entrar.';
  if (/invalid login credentials|invalid_credentials|invalid email or password/.test(text)) return 'E-mail ou senha incorretos. Confira os dados e tente novamente.';
  if (/too many requests|429|rate limit/.test(text)) return 'Muitas tentativas seguidas. Aguarde um pouco e tente novamente.';
  if (/supabase configuration unavailable|window\.supabase|script error/.test(text)) return 'A biblioteca de login não carregou. Confira a internet, recarregue a página e verifique se o CDN do Supabase está acessível.';
  if (/failed to fetch|fetch failed|network|load failed|offline|cors/.test(text)) return 'Não foi possível conectar ao Supabase. Confira a internet e abra o site pelo VS Code Live Server ou por HTTPS.';
  if (/42p01|pgrst205|42501|permission denied|does not exist|schema cache/.test(text)) return 'Não consegui verificar sua autorização no banco. Confira se o SQL do projeto foi aplicado no Supabase.';
  return error?.message || 'Não foi possível entrar. Confira a conexão e tente novamente.';
}
