    button.title = isDark ? 'Ativar tema claro' : 'Ativar tema escuro';
    button.innerHTML = `<i data-lucide="${isDark ? 'sun' : 'moon'}"></i><span>${isDark ? 'Tema claro' : 'Tema escuro'}</span>`;
