function renderCalendar(){const grid=$('calendarGrid'),monthTitle=$('calendarMonth');if(!grid||!monthTitle)return;const year=calendarCursor.getFullYear(),month=calendarCursor.getMonth(),first=new Date(year,month,1),start=new Date(year,month,1-first.getDay()),end=new Date(year,month,1-first.getDay()+41),today=isoDate(new Date()),events=calendarEvents(start,end),week=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];monthTitle.textContent=calendarCursor.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});let html=week.map(d=>`<div class="calendar-weekday">${d}</div>`).join('');for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const iso=isoDate(day),dayEvents=events.filter(e=>e.date===iso),classes=['calendar-day',day.getMonth()!==month?'outside':'',iso===today?'today':'',iso===selectedCalendarDate?'selected':''].filter(Boolean).join(' '),dots=[...new Set(dayEvents.map(e=>e.type))].map(type=>`<i class="dot-${type}"></i>`).join('');html+=`<button class="${classes}" data-date="${iso}" aria-label="${day.toLocaleDateString('pt-BR')}${dayEvents.length?`, ${dayEvents.length} itens`:''}"><span class="calendar-day-number">${day.getDate()}</span><span class="calendar-dots">${dots}</span></button>`;}grid.innerHTML=html;grid.querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{selectedCalendarDate=b.dataset.date;renderCalendar();renderCalendarDay();}));}
