async function markDebtInstallmentPaid(debtId,installment){const d=state.debts.find(x=>x.id===debtId);if(!d||!d.firstDueDate)return;const nextPaid=Math.max(0,Number(d.paidParcels)||0)+1;if(Number(installment)!==nextPaid||nextPaid>Number(d.totalParcels))return;const previous=cloneState(),paymentDate=addMonthsISO(d.firstDueDate,nextPaid-1);state.transactions.push({id:makeId(),type:'despesa',status:'pago',description:`Parcela ${nextPaid}/${d.totalParcels} · ${d.name}`,value:parseBRL(d.parcelValue),category:'Dívidas e parcelas',date:todayISO(),notes:`Pagamento da parcela com vencimento em ${paymentDate}.`});d.paidParcels=nextPaid;d.dueDate=debtNextDueDate(d);await commitStateChange(previous,'Parcela paga e sincronizada.');}
function deleteDebt(debtId){confirmDelete('Deseja realmente excluir esta dívida?',async()=>{const previous=cloneState();state.debts=state.debts.filter(d=>d.id!==debtId);await commitStateChange(previous,'Dívida excluída e sincronizada.');});}
function editSubscription(subId){const s=state.subscriptions.find(x=>x.id===subId);if(!s)return;$('formSub').reset();Object.entries({subId:s.id,subName:s.name,subValue:String(s.value).replace('.',','),subPeriod:s.period,subNextDate:s.nextDate,subStatus:s.status||'ativa'}).forEach(([k,v])=>$(k).value=v??'');$('modalTitleSub').textContent='Editar assinatura';openModal('modalSubOverlay');}
function deleteSubscription(subId){confirmDelete('Deseja realmente excluir esta assinatura?',async()=>{const previous=cloneState();state.subscriptions=state.subscriptions.filter(s=>s.id!==subId);await commitStateChange(previous,'Assinatura excluída e sincronizada.');});}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`finance-backup-${todayISO()}.json`;a.click();URL.revokeObjectURL(url);showToast('Backup exportado.');}
function normalizeBackup(data){const object=x=>x&&typeof x==='object'&&!Array.isArray(x),moneyValue=x=>{if(typeof x==='number')return Number.isFinite(x)&&x>=0;if(typeof x!=='string')return false;const text=x.trim().replace(/\s/g,'').replace(/^R\$/i,'');return /^(?:\d+|\d{1,3}(?:\.\d{3})+)(?:,\d{1,2})?$/.test(text)||/^\d+(?:\.\d{1,2})?$/.test(text);},validId=x=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(x||''));if(!object(data)||!Array.isArray(data.transactions)||!Array.isArray(data.debts)||!Array.isArray(data.subscriptions)||data.transactions.length+data.debts.length+data.subscriptions.length>10000)throw new Error('O arquivo não tem o formato esperado ou contém itens demais.');const transactions=data.transactions.map(t=>{if(!object(t)||!['receita','despesa'].includes(t.type)||!['pago','pendente'].includes(t.status)||typeof t.description!=='string'||!t.description.trim()||t.description.length>500||!moneyValue(t.value)||!isValidISODate(t.date))throw new Error('Há um lançamento inválido no backup.');return{id:validId(t.id)?t.id:makeId(),type:t.type,status:t.status,description:t.description.trim(),value:parseBRL(t.value),category:typeof t.category==='string'?t.category.slice(0,200):'',date:t.date,notes:typeof t.notes==='string'?t.notes.slice(0,2000):''};});const debts=data.debts.map(d=>{if(!object(d)||typeof d.name!=='string'||!d.name.trim()||d.name.length>500||!moneyValue(d.total)||!moneyValue(d.parcelValue)||!Number.isInteger(Number(d.totalParcels))||Number(d.totalParcels)<1||Number(d.totalParcels)>600||!Number.isInteger(Number(d.paidParcels))||Number(d.paidParcels)<0||Number(d.paidParcels)>Number(d.totalParcels))throw new Error('Há uma dívida inválida no backup.');const firstDueDate=d.firstDueDate|| (isValidISODate(d.dueDate)?addMonthsISO(d.dueDate,-Number(d.paidParcels)):'' );if(!isValidISODate(firstDueDate))throw new Error('Uma dívida não tem uma data inicial válida.');return{id:validId(d.id)?d.id:makeId(),name:d.name.trim(),total:parseBRL(d.total),parcelValue:parseBRL(d.parcelValue),totalParcels:Number(d.totalParcels),paidParcels:Number(d.paidParcels),firstDueDate,dueDate:addMonthsISO(firstDueDate,Number(d.paidParcels))};});const periods=['mensal','trimestral','semestral','anual'],statuses=['ativa','pausada','cancelada'],subscriptions=data.subscriptions.map(s=>{if(!object(s)||typeof s.name!=='string'||!s.name.trim()||s.name.length>500||!moneyValue(s.value)||!periods.includes(s.period)||!isValidISODate(s.nextDate)||!statuses.includes(s.status||'ativa'))throw new Error('Há uma assinatura inválida no backup.');return{id:validId(s.id)?s.id:makeId(),name:s.name.trim(),value:parseBRL(s.value),period:s.period,nextDate:s.nextDate,status:s.status||'ativa'};});return{transactions,debts,subscriptions};}
function importBackup(file){if(!file)return;const reader=new FileReader();reader.onload=async()=>{const previous=cloneState();try{state=normalizeBackup(JSON.parse(reader.result));if(!saveLocalData())throw new Error('Não foi possível salvar os dados neste navegador.');if(cloudReady&&!await replaceCloudProfile()){const primaryError=lastSyncError;state=previous;try{localStorage.setItem(profileStorageKey(),JSON.stringify(state));}catch(storageError){console.error(storageError);}let reconciled=false;try{reconciled=await replaceCloudProfile();}catch(syncError){console.error(syncError);}refresh();showToast(primaryError|| (reconciled?'O banco não confirmou a importação; os dados anteriores foram restaurados.':'A importação foi interrompida. Confira o banco e reaplique o backup se necessário.'),10000);return;}refresh();showToast(cloudReady?'Backup importado e sincronizado.':'Backup importado apenas neste navegador.');}catch(e){state=previous;try{localStorage.setItem(profileStorageKey(),JSON.stringify(state));}catch(storageError){console.error(storageError);}refresh();console.error(e);showToast(e.message||'Arquivo inválido ou não foi possível salvar o backup.');}};reader.readAsText(file);}
function resetDebtForm(){$('formDebt').reset();$('debtId').value='';$('modalTitleDebt').textContent='Nova dívida';$('debtTotalParcels').value=1;$('debtPaidParcels').value=0;$('firstDueDate').value=monthKey(dashboardMonth)+'-01';}
function resetSubForm(){$('formSub').reset();$('subId').value='';$('modalTitleSub').textContent='Nova assinatura';$('subStatus').value='ativa';}
